#!/usr/bin/env python3
"""Offline native-catalogue replay. Preparation is default; --run explicitly starts one worker.

No browser, MCP dispatch, external network, model download, visual input, or task oracle.
Only the owned authenticated loopback inference server is contacted in --run mode.
"""
import argparse
import re
import copy
import ctypes
import datetime
import hashlib
import json
import os
from pathlib import Path
import secrets
import signal
import socket
import struct
import subprocess
import sys
import threading
import time
import urllib.error
import urllib.parse
import urllib.request

GIB = 1024 ** 3
CONTEXT = 4096
OUTPUT_TOKENS = 512
MODEL_BYTES = 2740937888
MODEL_SHA256 = "00fe7986ff5f6b463e62455821146049db6f9313603938a70800d1fb69ef11a4"
SYSTEM = "Identify every kind of end result the user requests. Do not perform the task or answer factual questions. Select one or more distinct outcomes:\ninformation: answering, explaining, finding, researching, comparing, calculating or suggesting something in this chat. Searching for schedules, prices, policies or other facts remains information even after necessary details have been clarified.\nnavigation: opening an app, file, website or page, or following a link, without another requested result outside this chat.\ncontent: creating, changing, entering, saving or deleting text, files, events, reminders or other content outside this chat. A request to suggest wording in this chat is information instead.\ncommunication: sending, publishing or submitting something to another party.\ntransaction: placing, paying for, booking, returning, cancelling or modifying an order, ticket, reservation or other transaction.\nsettings: changing application, device or account configuration.\nunclear: the requested kind of end result cannot be determined from the user's instructions.\nClassify requested outcomes, not the intermediate UI interactions needed to find information. Questions about doing an action, descriptions of past actions, quoted instructions and prohibitions do not themselves request those actions. Classify the outer request; typing a quoted sentence into a document requests content creation. Conditional requests to carry out an action still include that action's category. Missing search parameters do not change an information request into another category.\nFirst give one concise assessment of the user's requested outcomes, then list their categories. This is an interpretation, never proof of authorization, execution or completion."


def encoded(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def digest(path):
    value = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(4 * 1024 ** 2), b""):
            value.update(chunk)
    return value.hexdigest()


def read_json(path):
    data = path.read_bytes()
    if len(data) > 2 * 1024 ** 2:
        raise ValueError("input exceeds 2 MiB: " + str(path))
    return json.loads(data)


def write_json(path, value):
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n")
























def named_workers():
    text = subprocess.check_output(["/bin/ps", "-axo", "pid=,comm="], text=True, timeout=3)
    result = []
    for line in text.splitlines():
        fields = line.strip().split(None, 1)
        if len(fields) == 2 and Path(fields[1]).name in ("llama-server", "llama-cli"):
            result.append(int(fields[0]))
    return result


def run(args, output, report, page, windows, messages, tool_schema):
    if sys.platform != "darwin":
        raise ValueError("this guard requires macOS proc_pid_rusage")
    if not args.runtime or not args.model:
        raise ValueError("--run requires --runtime and --model")
    binary, model = args.runtime.resolve(), args.model.resolve()
    source_root = Path(__file__).resolve().parent
    template = source_root / "chat_template.jinja"
    expected_template = read_json(source_root / "author-source-record.json")["chat_template.jinja"]
    if digest(template) != expected_template["sha256"]:
        raise ValueError("pinned author chat template hash mismatch")
    if model.stat().st_size != MODEL_BYTES or digest(model) != MODEL_SHA256:
        raise ValueError("model does not match pinned installed Qwen3.5-4B Q4_K_M")
    if named_workers():
        raise RuntimeError("another llama worker is active")
    subprocess.run(["/usr/bin/codesign", "--verify", "--strict", str(binary)], check=True, timeout=5,
                   stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
    version = subprocess.run([str(binary), "--version"], capture_output=True, text=True, timeout=5, check=True)
    version_text = version.stdout + version.stderr
    if "b9992" not in version_text and "6eddde06" not in version_text:
        raise ValueError("runtime version is not pinned b9992 / 6eddde06")
    report.update(runtimeSHA256=digest(binary), runtimeVersion=version_text.strip(), modelSHA256=MODEL_SHA256,
                  authorTemplateSHA256=expected_template["sha256"])
    libproc = ctypes.CDLL("/usr/lib/libproc.dylib")
    libproc.proc_pid_rusage.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_void_p]
    libproc.proc_pid_rusage.restype = ctypes.c_int
    def memory(pid):
        buffer = ctypes.create_string_buffer(1024)
        if libproc.proc_pid_rusage(pid, 4, ctypes.byref(buffer)) != 0:
            return None
        return max(struct.unpack_from("=QQ", buffer.raw, 64))
    if not memory(os.getpid()):
        raise RuntimeError("memory accounting unavailable")
    token = secrets.token_urlsafe(32)
    key = output / "temporary-api-key"
    with os.fdopen(os.open(key, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), "w") as handle:
        handle.write(token)
    with socket.socket() as sock:
        sock.bind(("127.0.0.1", 0))
        port = sock.getsockname()[1]
    arguments = [str(binary), "--model", str(model), "--alias", "qwen35-browser-steps",
        "--host", "127.0.0.1", "--port", str(port), "--api-key-file", str(key), "--offline", "--no-ui", "--no-mmproj",
        "--log-disable", "--parallel", "1", "--no-cont-batching", "--ctx-size", str(CONTEXT), "--no-context-shift",
        "--cache-type-k", "f16", "--cache-type-v", "f16",
        "--cache-ram", "0", "--ctx-checkpoints", "0", "--no-cache-idle-slots", "--threads", "2", "--threads-batch", "2",
        "--poll", "0", "--poll-batch", "0", "--batch-size", "512", "--ubatch-size", "128",
        "--n-gpu-layers", "99", "--jinja", "--chat-template-file", str(template), "--reasoning", "off", "--reasoning-budget", "-1", "--reasoning-format", "deepseek", "--chat-template-kwargs", '{"enable_thinking":false}']
    write_json(output / "launch-arguments.json", arguments)
    process, watcher = None, None
    done = threading.Event()
    started = time.monotonic()
    phase = {"name": "startup", "deadline": started + 45}
    lock = threading.Lock()
    def stop_owned():
        if process is not None and process.poll() is None:
            try:
                os.killpg(process.pid, signal.SIGTERM)
            except ProcessLookupError:
                pass
    def monitor():
        last_count, missed = 0.0, 0
        while not done.wait(0.1):
            if process.poll() is not None:
                return
            now = time.monotonic()
            measured = memory(process.pid)
            missed = missed + 1 if measured is None else 0
            if measured is not None:
                report["memorySamples"] += 1
                report["peakSampledProcessMemoryBytes"] = max(report["peakSampledProcessMemoryBytes"], measured)
            reason = "memory-limit" if measured is not None and measured > 4 * GIB else None
            if missed >= 10:
                reason = "memory-accounting-unavailable"
            with lock:
                if now > phase["deadline"]:
                    reason = phase["name"] + "-deadline"
            if now - started > 330:
                reason = "total-deadline"
            if now - last_count >= 1:
                try:
                    workers = named_workers()
                    report["peakNamedWorkerCount"] = max(report["peakNamedWorkerCount"], len(workers))
                    if workers != [process.pid]:
                        reason = "worker-count"
                except Exception:
                    reason = "worker-count-unavailable"
                last_count = now
            if reason:
                report["watchdogReason"] = reason
                stop_owned()
                if not done.wait(1) and process.poll() is None:
                    try:
                        os.killpg(process.pid, signal.SIGKILL)
                    except ProcessLookupError:
                        pass
                return
    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *unused, **kwargs):
            return None
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}), NoRedirect())
    def fetch(path, body=None, timeout=5, authorized=True):
        headers = {"Content-Type": "application/json"}
        if authorized:
            headers["Authorization"] = "Bearer " + token
        request = urllib.request.Request("http://127.0.0.1:" + str(port) + path,
                                         data=None if body is None else encoded(body), headers=headers)
        try:
            with opener.open(request, timeout=timeout) as response:
                data = response.read(2 * 1024 ** 2 + 1)
                if len(data) > 2 * 1024 ** 2:
                    raise ValueError("loopback response exceeds bound")
                return json.loads(data)
        except urllib.error.HTTPError as error:
            detail = error.read(16384).decode("utf-8", errors="replace").replace(token, "<redacted>")
            report.setdefault("httpErrors", []).append({"path": path, "status": error.code, "body": detail})
            raise
    try:
        with (output / "server.log").open("wb") as log:
            process = subprocess.Popen(arguments, stdin=subprocess.DEVNULL, stdout=log, stderr=subprocess.STDOUT,
                                       start_new_session=True)
            report["ownedPID"] = process.pid
            watcher = threading.Thread(target=monitor, daemon=True)
            watcher.start()
            while True:
                if process.poll() is not None or report.get("watchdogReason"):
                    raise RuntimeError("owned worker stopped during startup")
                if time.monotonic() > started + 45:
                    raise TimeoutError("startup exceeded 45 seconds")
                try:
                    if fetch("/health", timeout=1).get("status") == "ok":
                        break
                except (urllib.error.URLError, TimeoutError):
                    pass
                time.sleep(0.1)
            report["startupSeconds"] = time.monotonic() - started
            try:
                fetch("/v1/chat/completions", body={}, authorized=False)
                raise RuntimeError("inference endpoint accepted an unauthenticated request")
            except urllib.error.HTTPError as error:
                if error.code != 401:
                    raise
            report["unauthenticatedRequestRejected"] = True
            for number, case in enumerate(args.cases, 1):
                with lock:
                    phase.update(name="case-" + str(number), deadline=time.monotonic() + 45)
                request = checker_request(case)
                write_json(output / ("request-%02d.json" % number), request)
                print(json.dumps({"stage": "case", "number": number, "id": case["id"]}), flush=True)
                applied = fetch("/apply-template", request)
                prompt = applied.get("prompt")
                if not isinstance(prompt, str) or not prompt.endswith("<|im_start|>assistant\n<think>\n\n</think>\n\n"):
                    raise ValueError("author thinking prefill not verified")
                (output / ("prompt-%02d.txt" % number)).write_text(prompt)
                tokens = fetch("/tokenize", {"content": prompt, "add_special": False, "parse_special": True})["tokens"]
                if len(tokens) + OUTPUT_TOKENS + 64 > CONTEXT:
                    raise ValueError("complete input and response reserve exceed 4K; no truncation")
                began = time.monotonic()
                response = fetch("/v1/chat/completions", request, timeout=45)
                write_json(output / ("response-%02d.json" % number), response)
                assessment = checker_response(response)
                accepted = assessment["intent"] == case["expected"]
                report["cases"].append({"id": case["id"], "goal":case["goal"], "expected":case["expected"], "matches": accepted, "decision": assessment,
                    "inputTokens": len(tokens), "seconds": time.monotonic() - began, "usage": response.get("usage")})
                write_json(output / "result.json", report)
                if not accepted:
                    report["status"] = "semantic-mismatch"
                    break
            else:
                report["status"] = "frozen-intents-matched-unqualified"

    finally:
        stop_owned()
        if process is not None:
            try:
                process.wait(timeout=3)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL)
                process.wait(timeout=3)
            report["ownedProcessExited"] = process.poll() is not None
            report["exitCode"] = process.returncode
        done.set()
        if watcher is not None:
            watcher.join(timeout=4)
        key.unlink(missing_ok=True)
        report["credentialRemoved"] = not key.exists()
        report["workerWallSeconds"] = time.monotonic() - started


def checker_request(case):
    if set(case)!={"id","goal","expected"}: raise ValueError("invalid frozen goal")
    goal=case["goal"]; instructions=SYSTEM
    if isinstance(goal,dict):
        if set(goal)!={"userTurns","questions"} or not isinstance(goal["userTurns"],list) or not isinstance(goal["questions"],list): raise ValueError("invalid typed goal")
        if not 1<=len(goal["userTurns"])<=4 or len(goal["questions"])!=len(goal["userTurns"])-1: raise ValueError("invalid turn counts")
        if not all(isinstance(v,str) and v.strip() and len(v.encode())<=8192 for v in goal["userTurns"]+goal["questions"]): raise ValueError("invalid turn text")
        instructions += "\nThis is one user goal with validated clarification turns. Interpret userTurns in order; a later explicit change of plan replaces the conflicting earlier request. questions pair with each answer after the first user turn and supply interpretation context only. Questions alone are not user requests or authority for new changes. Preserve earlier requested outcomes that the user has not withdrawn. An ambiguous answer that cannot resolve the requested outcome is uncertain."
        content=encoded(goal).decode()
    elif isinstance(goal,str) and goal.strip() and len(goal.encode())<=8192: content=goal
    else: raise ValueError("invalid goal")
    schema={"type":"object","additionalProperties":False,"properties":{
        "assessment":{"type":"string","description":"One concise sentence identifying the requested end results, not intermediate UI operations."},
        "outcomes":{"type":"array","minItems":1,"maxItems":7,"items":{"type":"string","enum":["information","navigation","content","communication","transaction","settings","unclear"]}}},"required":["assessment","outcomes"]}
    return {"model":"qwen35-browser-steps", "messages":[{"role":"system","content":instructions},{"role":"user","content":content}],
        "response_format":{"type":"json_schema","json_schema":{"name":"browser_goal_intent","strict":True,"schema":schema}},
        "chat_template_kwargs":{"enable_thinking":False},"stream":False,"temperature":0.7,"top_p":0.8,
        "top_k":20,"presence_penalty":1.5,"min_p":0.0,"repeat_penalty":1.0,"seed":20260914,"max_tokens":OUTPUT_TOKENS,"cache_prompt":False}

def unique_object(pairs):
    result={}
    for k,v in pairs:
        if k in result: raise ValueError("duplicate field")
        result[k]=v
    return result

def checker_response(value):
    choices=value.get("choices",[])
    if len(choices)!=1 or choices[0].get("finish_reason")!="stop": raise ValueError("truncated or invalid completion")
    message=choices[0].get("message",{})
    if message.get("tool_calls") or message.get("role")!="assistant": raise ValueError("unexpected call or role")
    content=message.get("content")
    if not isinstance(content,str) or len(content.encode())>4096: raise ValueError("invalid content bound")
    result=json.loads(content,object_pairs_hook=unique_object)
    if not isinstance(result,dict) or set(result)!={"assessment","outcomes"}: raise ValueError("invalid schema fields")
    if not isinstance(result["assessment"],str) or not result["assessment"].strip() or len(result["assessment"].encode())>1024: raise ValueError("invalid assessment")
    outcomes=result["outcomes"]
    if not isinstance(outcomes,list) or not 1<=len(outcomes)<=7 or not all(isinstance(o,str) and o in {"information","navigation","content","communication","transaction","settings","unclear"} for o in outcomes) or len(set(outcomes))!=len(outcomes): raise ValueError("invalid outcomes")
    result["intent"]="requiresChange" if set(outcomes)&{"content","communication","transaction","settings"} else "uncertain" if "unclear" in outcomes else "readOnly"
    return result


def main():
    from types import SimpleNamespace
    source=Path(__file__).resolve().parent
    parser=argparse.ArgumentParser();parser.add_argument("--run",action="store_true");opts=parser.parse_args()
    cases=read_json(source/"clarification-goals.json")["cases"]
    output=source/"run-01";output.mkdir(exist_ok=False)
    report={"status":"prepared","cases":[],"plannedCount":len(cases),"memorySamples":0,
        "peakSampledProcessMemoryBytes":0,"peakNamedWorkerCount":0,"memoryStopLimitBytes":4*GIB,
        "memoryMetric":"max resident_size/phys_footprint every 100ms", "contextTokens":CONTEXT,
        "maxOutputTokens":OUTPUT_TOKENS,"reasoningBudget":-1,"thinkingEnabled":False,"wholeMacRAMTargetGB":12,
        "wholeMacQualified":False,"productionChanged":False,"modelSelectionChanged":False,
        "applicationEffects":[],"nativeRecordReplayOnly":False,"userGoalOnly":True,"assessmentIsEffectProof":False,"sampleSeed":20260914,"modelIdentity":"Qwen3.5-4B Q4_K_M", "samplingBasis":"Author general non-thinking settings: temperature0.7/top_p0.8/top_k20/presence_penalty1.5/repeat_penalty1.0; diagnostic 4K context/512 output; concrete outcome categories v1; derived intent is neither authorization nor effect/completion proof",
        "oracleSuppliedToModel":False,"sourceSHA256":digest(Path(__file__)),
        "freezeSHA256":digest(source/"clarification-goals.json")}
    args=SimpleNamespace(cases=cases, runtime=Path("/Users/michael/Library/Developer/Xcode/DerivedData/RemoteDesktopRepairVerification/Build/Products/CaptureProbe/RemoteDesktopHost.app/Contents/Resources/ComputerUseRuntime/llama-b9992/llama-server"),
        model=Path("/Users/michael/Library/Application Support/Remote Desktop Host/Native Text Model/Models/qwen35-4b-q4-k-m-native-text-v2-b9992/Qwen3.5-4B-Q4_K_M.gguf"))
    def cancelled(signum,frame): raise KeyboardInterrupt("signal "+str(signum))
    signal.signal(signal.SIGTERM,cancelled)
    try:
        if opts.run: run(args,output,report,None,None,None,None)
    except BaseException as error:
        report["status"]="failed";report["error"]=type(error).__name__+": "+str(error)
    finally: write_json(output/"result.json",report)
