def checker_request(case):
    if set(case)!={"id","goal","expected"}: raise ValueError("invalid frozen goal")
    goal=case["goal"]; instructions=SYSTEM
    if isinstance(goal,dict):
        if set(goal)!={"userTurns","questions"} or not isinstance(goal["userTurns"],list) or not isinstance(goal["questions"],list): raise ValueError("invalid typed goal")
        if not 1<=len(goal["userTurns"])<=4 or len(goal["questions"])!=len(goal["userTurns"])-1: raise ValueError("invalid turn counts")
        if not all(isinstance(v,str) and v.strip() and len(v.encode())<=8192 for v in goal["userTurns"]+goal["questions"]): raise ValueError("invalid turn text")
        instructions += "\nThis is one user goal with validated clarification turns. Interpret userTurns in order; a later explicit change of plan replaces the conflicting earlier request. questions pair with each answer after the first user turn and supply interpretation context only. Questions alone are not user requests or authority for new changes. Preserve earlier requested outcomes that the user has not withdrawn. An ambiguous answer that cannot resolve the requested outcome is uncertain."
        content=encoded(goal).decode()
    elif isinstance(goal,str) and goal.strip() and len(goal.encode())<=8192: content=goal
    else: raise ValueError("invalid goal")
    schema={"type":"object","additionalProperties":False,"properties":{
        "assessment":{"type":"string","description":"One concise sentence identifying the requested end results, not intermediate UI operations."},
        "outcomes":{"type":"array","minItems":1,"maxItems":7,"items":{"type":"string","enum":["information","navigation","content","communication","transaction","settings","unclear"]}}},"required":["assessment","outcomes"]}
    return {"model":"agents-a1-goal-outcomes", "messages":[{"role":"system","content":instructions},{"role":"user","content":content}],
        "response_format":{"type":"json_schema","json_schema":{"name":"browser_goal_intent","strict":True,"schema":schema}},
        "chat_template_kwargs":{"enable_thinking":False},"stream":False,"temperature":0.85,"top_p":0.95,
        "top_k":20,"presence_penalty":1.1,"min_p":0.0,"repeat_penalty":1.0,"seed":20260914,"max_tokens":OUTPUT_TOKENS,"cache_prompt":False}

def unique_object(pairs):
    result={}
    for k,v in pairs:
        if k in result: raise ValueError("duplicate field")
        result[k]=v
    return result

def checker_response(value):
    choices=value.get("choices",[])
    if len(choices)!=1 or choices[0].get("finish_reason")!="stop": raise ValueError("truncated or invalid completion")
    message=choices[0].get("message",{})
    if message.get("tool_calls") or message.get("role")!="assistant": raise ValueError("unexpected call or role")
    content=message.get("content")
    if not isinstance(content,str) or len(content.encode())>4096: raise ValueError("invalid content bound")
    result=json.loads(content,object_pairs_hook=unique_object)
    if not isinstance(result,dict) or set(result)!={"assessment","outcomes"}: raise ValueError("invalid schema fields")
    if not isinstance(result["assessment"],str) or not result["assessment"].strip() or len(result["assessment"].encode())>1024: raise ValueError("invalid assessment")
    outcomes=result["outcomes"]
    if not isinstance(outcomes,list) or not 1<=len(outcomes)<=7 or not all(isinstance(o,str) and o in {"information","navigation","content","communication","transaction","settings","unclear"} for o in outcomes) or len(set(outcomes))!=len(outcomes): raise ValueError("invalid outcomes")
    result["intent"]="requiresChange" if set(outcomes)&{"content","communication","transaction","settings"} else "uncertain" if "unclear" in outcomes else "readOnly"
    return result


